function intellectReportMarkup(report) {
  if (!report?.results) return '';
  const symbols = { 'Foco profundo': '🎯', 'Pensamiento crítico': '🧩', Memoria: '🧠', Aprendizaje: '💡', Planificación: '🗺️' };
  return `${initialLevelsMarkup(report.initialLevels)}<section class="panel intellect-report"><div><p class="eyebrow">MAPA INTELECTUAL INICIAL</p><h3>Nivel ${report.initialLevel}/60 · ${report.totalCorrect} de ${report.totalQuestions} correctas</h3><p>El 60 sólo se alcanza con una evaluación perfecta. Los niveles 61 a 100 se construyen con evidencia y XP.</p></div><div class="intellect-result-grid">${Object.entries(report.results).map(([skill, result]) => `<article><span>${symbols[skill]}</span><div><b>${skill}</b><small>${result.correct}/${result.total} evidencias correctas</small></div><strong>${result.score}/60</strong></article>`).join('')}</div></section>`;
}

function initialLevelsMarkup(levels={}) {
  const symbols={Intelecto:'🧠',Carisma:'🗣️',Rendimiento:'⚡',Físico:'🦾'};
  return `<section class="panel initial-levels"><div><p class="eyebrow">NIVELES DE INICIO</p><h3>Tu punto de partida, no tu techo</h3><p>La evaluación puede ubicarte entre 1 y 60. Desde ahora cada barra exige más XP cuanto mayor sea el nivel.</p></div><div>${Object.entries(symbols).map(([attribute,symbol])=>`<article><span>${symbol}</span><small>${attribute}</small><b>${levels[attribute]||1}<i>/60</i></b></article>`).join('')}</div></section>`;
}

