function finishWorkout() {
  const state = getState(), day = state.training.weeklyPlan[state.training.selectedDay], sets = day.exercises.flatMap(exercise => exercise.setData);
  const volume = sets.reduce((sum, set) => sum + set.kg * set.reps, 0), rpe = sets.length ? (sets.reduce((sum, set) => sum + set.rpe, 0) / sets.length).toFixed(1) : 0;
  const reward=state.plan?.rewards?.training||180,isToday=day.day===state.daily.dayName;
  const sportAlreadyDone=!day.sport||state.training.sportHistory.some(entry=>entry.dateKey===state.daily.dateKey&&entry.day===day.day);
  const rewardReady=isToday&&sportAlreadyDone;
  const rewardCopy=!isToday
    ? 'La sesión se guarda, pero sólo la actividad asignada para hoy entrega XP.'
    : rewardReady
      ? `Completaste la actividad asignada: suma <b>+${reward} XP</b>.`
      : `El gimnasio queda guardado. Completá también <b>${esc(day.sport.name)}</b> para recibir los <b>+${reward} XP</b>.`;
  modal(`<p class="eyebrow">SESIÓN COMPLETA</p><h2>Buen trabajo.</h2><div class="battle-result"><span>Volumen <b>${volume} kg</b></span><span>RPE medio <b>${rpe}</b></span><span>Series <b>${sets.filter(set => set.done).length}/${sets.length}</b></span></div><p>${rewardCopy}</p><button class="primary full" id="save-workout">GUARDAR${rewardReady?` · +${reward} XP`:''}</button>`);
  document.querySelector('#save-workout').onclick = () => { let delta=0,pendingSport=false; mutate(current => { current.training.history.unshift({ at: Date.now(), dateKey: current.daily.dateKey, day: day.day, activityType:'gym', volume, rpe }); current.training.current = 0; day.exercises.forEach(exercise => exercise.setData.forEach(set => set.done = false)); const sportDone=!day.sport||current.training.sportHistory.some(entry=>entry.dateKey===current.daily.dateKey&&entry.day===day.day);pendingSport=isToday&&!sportDone;const trainingHabit = current.habits.find(habit => habit.catalogId === 'daily-training'); if (trainingHabit&&sportDone) trainingHabit.done = true; if(isToday&&sportDone)delta=recordXp(current,{key:`training-${current.daily.dateKey}-${day.day}`,amount:reward,label:`Actividad completa: ${day.title}`,type:'training'}); }); document.querySelector('#modal').innerHTML = ''; toast(delta?`Actividad completa · +${delta} XP`:pendingSport?'Gimnasio guardado · falta completar el deporte':'Entrenamiento guardado'); };
}

function missionModal(id){
  if (!planEditable(getState())) return toast('El plan Hardcore está bloqueado. Las misiones no se pueden editar.');
  const mission=getState().missions.find(item=>item.id===id);
  if(!mission)return;
  modal(`<p class="eyebrow">EDITAR MISIÓN</p><h2>Ajustá la tarea asignada</h2><form id="mission-form" class="note-form"><label>Título<input name="title" value="${esc(mission.title)}" required></label><label>Objetivo concreto<textarea name="detail" rows="5" required>${esc(mission.detail)}</textarea></label><p class="editor-explanation">La recompensa de <b>+${mission.xp} XP</b> se mantiene para conservar el equilibrio.</p><button class="primary full">GUARDAR MISIÓN</button></form>`);
  document.querySelector('#mission-form').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));mutate(state=>Object.assign(state.missions.find(item=>item.id===id),data));document.querySelector('#modal').innerHTML='';};
}

function startBoostGame(index) {
  const challenges=[
    {name:'Reflejo relámpago',prompt:'Tocá el número objetivo: 7',answer:'7',options:['3','7','9','2','5','1']},
    {name:'Patrón de guardia',prompt:'Completá la secuencia: 2 · 4 · 8 · ?',answer:'16',options:['10','12','16','18']},
    {name:'Memoria de runas',prompt:'La runa LUNA estaba unida al 4. ¿Cuál elegís?',answer:'4',options:['7','2','4','9']},
  ];
  const challenge=challenges[index];
  if(!challenge)return;
  modal(`<p class="eyebrow">MINIJUEGO ${index+1} / 3</p><h2>${challenge.name}</h2><p>${challenge.prompt}</p><div class="game-board">${challenge.options.map(option=>`<button data-game-answer="${option}">${option}</button>`).join('')}</div><small>Si fallás, podés volver a intentarlo durante esta partida.</small>`);
  document.querySelectorAll('[data-game-answer]').forEach(button=>button.onclick=()=>{
    if(button.dataset.gameAnswer!==challenge.answer){button.classList.add('wrong');toast('No era esa. Probá otra vez.');return;}
    mutate(state=>{const boost=state.arena.battle?.boosts[index];if(boost)boost.unlocked=true;},{type:'arena',label:`Boost desbloqueado: ${challenge.name}`});
    document.querySelector('#modal').innerHTML='';toast('Boost desbloqueado. Ya podés usarlo.');
  });
}

function saveAvatarFile(file){
  if(!file?.type.startsWith('image/'))return toast('Elegí una imagen válida');
  if(file.size>8*1024*1024)return toast('La imagen supera 8 MB');
  const reader=new FileReader();
  reader.onload=()=>{const image=new Image();image.onload=()=>{const size=512,canvas=document.createElement('canvas'),context=canvas.getContext('2d');canvas.width=size;canvas.height=size;const crop=Math.min(image.width,image.height),x=(image.width-crop)/2,y=(image.height-crop)/2;context.drawImage(image,x,y,crop,crop,0,0,size,size);mutate(state=>{state.profile.avatarImage=canvas.toDataURL('image/jpeg',.84);});toast('Foto de perfil actualizada');};image.src=reader.result;};
  reader.readAsDataURL(file);
}

function decorateHabitCards(){
  const state=getState();
  const fallbackEmoji={Sueño:'🌙',Agua:'💧',Movimiento:'👟','Alimentación estructurada':'🍽️',Foco:'🎯',Aprendizaje:'💡','Comunicación intencional':'💬'};
  document.querySelectorAll('[data-habit-toggle]').forEach(button=>{
    if(button.querySelector('.habit-symbol'))return;
    const habit=state.habits.find(item=>item.id===button.dataset.habitToggle);
    const template=habitCatalog.find(item=>item.id===habit?.catalogId||item.name===habit?.name);
    const symbol=document.createElement('span');
    symbol.className='habit-symbol';
    symbol.textContent=habit?.emoji||template?.emoji||fallbackEmoji[habit?.name]||'⭐';
    button.insertBefore(symbol,button.querySelector('b'));
    if(!button.querySelector('.habit-xp-label')&&habit?.catalogId!=='daily-training'){
      const reward=document.createElement('small');reward.className='habit-xp-label';reward.textContent=`+${state.plan?.rewards?.habit||25} XP`;button.append(reward);
    }
  });
  const addButton=document.querySelector('[data-habit-add]');
  if(addButton&&!document.querySelector('[data-habit-library]')){const libraryButton=document.createElement('button');libraryButton.className='ghost';libraryButton.dataset.habitLibrary='';libraryButton.innerHTML='📚 Elegir lista';addButton.before(libraryButton);}
}

