  decorateHabitCards();
  decoratePlanUi();
  enhanceWeeklyOverviews();
  document.querySelector('[data-daily-welcome]')?.addEventListener('click', () => mutate(state => state.daily.welcomeSeenDate = state.daily.dateKey));
