  document.querySelector('[data-recalibrate]')?.addEventListener('click', () => {if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');mutate(state => { const done = state.missions.filter(mission => mission.status === 'done'),covered=new Set(done.map(mission=>attributeForActivity('mission',mission.category,mission.title))); state.daily.recalibrations = (state.daily.recalibrations || 0) + 1; const replacements=generateMissions(state, new Date(), state.daily.recalibrations).filter(mission=>!covered.has(attributeForActivity('mission',mission.category,mission.title)));state.missions=[...done,...replacements].slice(0,4); });});
