  document.querySelector('[data-habit-library]')?.addEventListener('click', habitLibraryModal);
  document.querySelectorAll('[data-habit-edit]').forEach(button => button.onclick = () => habitModal(button.dataset.habitEdit));
  document.querySelectorAll('[data-habit-delete]').forEach(button => button.onclick = () => mutate(state => state.habits = state.habits.filter(habit => habit.id !== button.dataset.habitDelete)));
  document.querySelector('#notepad')?.addEventListener('submit', event => { event.preventDefault(); const content=new FormData(event.target).get('content');mutate(state=>state.notepad={content,updatedAt:Date.now()});toast('Bloc de notas guardado'); });
  document.querySelectorAll('[data-sport-config]').forEach(button=>button.addEventListener('click',sportConfigModal));

  document.querySelectorAll('[data-routine-type]').forEach(button => button.onclick = () => {
    if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');
    const type = button.dataset.routineType, labels = { 'heavy-duty': 'Heavy Duty', hypertrophy: 'Hipertrofia', strength: 'Fuerza', 'full-body': 'Full Body' };
    mutate(state => {const trainingDays=state.training.weeklyPlan.filter(day=>day.enabled).map(day=>day.day),answers={...state.onboardingAnswers,routineType:type,trainingDays,weeklyFrequency:String(trainingDays.length||state.training.settings.days)};state.training.settings.type=type;state.onboardingAnswers.routineType=type;state.training.weeklyPlan=buildTrainingPlan(answers);state.training.selectedDay=Math.max(0,state.training.weeklyPlan.findIndex(day=>day.enabled||day.sport));state.training.current=0;});
    toast(`${labels[type]} aplicada · series, repeticiones y descansos adaptados`);
  });
  document.querySelector('[data-generate-routine]')?.addEventListener('click', () => {if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');mutate(state => { const trainingDays=state.training.weeklyPlan.filter(day=>day.enabled).map(day=>day.day);const answers = { ...state.onboardingAnswers, routineType: state.training.settings.type, trainingDays, weeklyFrequency: String(trainingDays.length||state.training.settings.days) }; state.training.weeklyPlan = buildTrainingPlan(answers); state.training.selectedDay = Math.max(0, state.training.weeklyPlan.findIndex(day => day.enabled)); state.training.current = 0; });});
  document.querySelectorAll('[data-training-split]').forEach(button=>button.onclick=()=>{if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');mutate(state=>{const day=state.training.weeklyPlan[Number(button.dataset.splitDay)],split=button.dataset.trainingSplit,labels={'heavy-duty':'Heavy Duty',hypertrophy:'Hipertrofia',strength:'Fuerza','full-body':'Full Body'};day.split=split;day.title=`${labels[state.training.settings.type]} · ${split==='lower'?'Tren inferior':'Tren superior'}`;day.exercises=buildTrainingDay(state.training.settings.type,split);state.training.selectedDay=Number(button.dataset.splitDay);state.training.current=0;});});
  document.querySelectorAll('[data-training-day]').forEach(button => button.onclick = () => mutate(state => { state.training.selectedDay = Number(button.dataset.trainingDay); state.training.current = 0; }));
  document.querySelectorAll('[data-exercise-jump]').forEach(button=>button.onclick=()=>{mutate(state=>{state.training.selectedDay=Number(button.dataset.exerciseDay);state.training.current=Number(button.dataset.exerciseJump);});requestAnimationFrame(()=>document.querySelector('.session-head')?.scrollIntoView({behavior:'smooth',block:'start'}));});
  document.querySelectorAll('[data-week-training-edit]').forEach(button=>button.onclick=()=>{if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');routineDayModal(Number(button.dataset.weekTrainingEdit));});
  document.querySelector('[data-sport-done]')?.addEventListener('click',()=>{const index=Number(document.querySelector('[data-sport-done]').dataset.sportDone),state=getState(),day=state.training.weeklyPlan[index];if(state.training.sportHistory.some(entry=>entry.dateKey===state.daily.dateKey&&entry.day===day.day))return toast('El deporte ya está registrado');let delta=0,pendingGym=false;mutate(current=>{current.training.sportHistory.unshift({at:Date.now(),dateKey:current.daily.dateKey,day:day.day,sport:day.sport.name,duration:day.sport.duration,intensity:day.sport.intensity});const gymDone=!day.enabled||current.training.history.some(entry=>entry.dateKey===current.daily.dateKey&&entry.day===day.day);pendingGym=day.day===current.daily.dayName&&!gymDone;const habit=current.habits.find(item=>item.catalogId==='daily-training');if(habit&&gymDone)habit.done=true;if(day.day===current.daily.dayName&&gymDone)delta=recordXp(current,{key:`training-${current.daily.dateKey}-${day.day}`,amount:current.plan?.rewards?.training||180,label:`Actividad completa: ${day.title}`,type:'training'});});toast(delta?`Actividad completa · +${delta} XP`:pendingGym?'Deporte guardado · falta completar el gimnasio':'Deporte registrado');});
  document.querySelector('[data-edit-routine-day]')?.addEventListener('click', ()=>routineDayModal());
  document.querySelectorAll('[data-set]').forEach(input => input.onchange = () => mutate(state => state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData[Number(input.dataset.set)][input.dataset.field] = Number(input.value)));
  document.querySelectorAll('[data-set-done]').forEach(button => button.onclick = () => mutate(state => { const set = state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData[Number(button.dataset.setDone)]; set.done = !set.done; }));
  document.querySelector('[data-set-add]')?.addEventListener('click', () => {const state=getState(),exercise=state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current];if(exercise.setData.length>=5)return toast('El máximo es de 5 series por ejercicio');mutate(current=>{const target=current.training.weeklyPlan[current.training.selectedDay].exercises[current.training.current],count=target.setData.length+1,progression=repetitionProgression(target.reps,count,current.training.settings.type),effort=effortProgression(count,current.training.settings.type),last=target.setData.at(-1);target.setData.push({kg:last?.kg||0,reps:progression[count-1],rpe:effort[count-1],done:false});target.sets=count;});});
  document.querySelector('[data-set-remove]')?.addEventListener('click', () => mutate(state => { const sets = state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].setData; if (sets.length > 1) sets.pop(); }));
  document.querySelector('[data-ex-prev]')?.addEventListener('click', () => mutate(state => state.training.current--));
  document.querySelector('[data-ex-next]')?.addEventListener('click', () => { const state = getState(), day = state.training.weeklyPlan[state.training.selectedDay]; if (state.training.current < day.exercises.length - 1) mutate(current => current.training.current++); else finishWorkout(); });
  document.querySelector('[data-training-note]')?.addEventListener('change', event => mutate(state => state.training.weeklyPlan[state.training.selectedDay].exercises[state.training.current].notes = event.target.value));
  document.querySelector('[data-timer]')?.addEventListener('click', () => { if (timerId) { clearInterval(timerId); timerId = null; return; } const start = Date.now(); timerId = setInterval(() => { const clock = document.querySelector('#timer'); if (!clock) return clearInterval(timerId); const seconds = Math.floor((Date.now() - start) / 1000); clock.textContent = `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }, 250); });

  document.querySelectorAll('[data-nutrition-day]').forEach(button => button.onclick = () => mutate(state => state.nutrition.selectedDay = Number(button.dataset.nutritionDay)));
  document.querySelectorAll('[data-week-nutrition-edit]').forEach(button=>button.onclick=()=>{if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');mutate(state=>state.nutrition.selectedDay=Number(button.dataset.weekNutritionEdit));nutritionDayModal();});
  document.querySelectorAll('[data-week-meal-edit]').forEach(button=>button.onclick=()=>{if(!planEditable(getState()))return toast('El plan Hardcore está bloqueado');mutate(state=>state.nutrition.selectedDay=Number(button.dataset.mealDay));mealModal(Number(button.dataset.weekMealEdit));});
  document.querySelector('[data-edit-nutrition-day]')?.addEventListener('click', nutritionDayModal);
  document.querySelectorAll('[data-edit-meal]').forEach(button => button.onclick = () => mealModal(Number(button.dataset.editMeal)));
  document.querySelectorAll('[data-meal-done]').forEach(button => button.onclick = () => {let delta=0,isToday=false;mutate(state => { const id=button.dataset.mealDone,day=state.nutrition.weeklyPlan[state.nutrition.selectedDay],wasDone=state.nutrition.done.includes(id);isToday=day.day===state.daily.dayName;state.nutrition.done=wasDone?state.nutrition.done.filter(item=>item!==id):[...state.nutrition.done,id];if(isToday)delta=recordXp(state,{key:`meal-${state.daily.dateKey}-${id}`,amount:state.plan?.rewards?.meal||20,label:`Comida: ${day.meals.find(meal=>meal.id===id)?.name||id}`,type:'nutrition',reverse:wasDone});});toast(!isToday?'Comida registrada · el XP corresponde al plan de hoy':delta>0?`Comida completada · +${delta} XP`:delta<0?`${Math.abs(delta)} XP revertidos`:'Comida actualizada');});
  document.querySelectorAll('[data-favorite]').forEach(button => button.onclick = () => mutate(state => { const id = button.dataset.favorite; state.nutrition.favorites = state.nutrition.favorites.includes(id) ? state.nutrition.favorites.filter(item => item !== id) : [...state.nutrition.favorites, id]; }));
  document.querySelector('[data-shop-list]')?.addEventListener('click', shoppingListModal);
  document.querySelector('[data-nut-save]')?.addEventListener('click', () => mutate(state => { state.nutrition.weight = document.querySelector('#weight').value; state.nutrition.hunger = Number(document.querySelector('#hunger').value); state.nutrition.energy = Number(document.querySelector('#nut-energy').value); }));

  document.querySelectorAll('[data-course]').forEach(button => button.onclick = () => { sessionStorage.setItem('course', button.dataset.course); render(); });
  document.querySelector('[data-course-back]')?.addEventListener('click', () => { sessionStorage.removeItem('course'); render(); });
  document.querySelectorAll('[data-lesson]').forEach(button => button.onclick = () => {let delta=0;mutate(state => { if (!state.academy.completed.includes(button.dataset.lesson)) { state.academy.completed.push(button.dataset.lesson);delta=recordXp(state,{key:`lesson-${button.dataset.lesson}`,amount:50,label:'Lección completada',type:'lesson'}); } });toast(delta?`Lección completada · +${delta} XP`:'La lección ya estaba completada');});
  document.querySelector('[data-quiz]')?.addEventListener('click', event => { const value = document.querySelector('input[name=quiz]:checked')?.value; if (value == null) return toast('Elegí una respuesta'); const score = value === '1' ? 100 : 0,quizId=event.currentTarget.dataset.quiz;let delta=0; mutate(state => { state.academy.quizScores[quizId] = score; if (score)delta=recordXp(state,{key:`quiz-${quizId}`,amount:100,label:'Quiz aprobado',type:'quiz'}); }); toast(score ? delta?`Quiz aprobado · +${delta} XP`:'Quiz aprobado · XP ya acreditada' : 'Revisá la lección'); });
  document.querySelectorAll('[data-arena-mode]').forEach(button=>button.onclick=()=>mutate(state=>{state.arena.selectedMode=button.dataset.arenaMode;state.arena.battle=createArenaBattle(state,button.dataset.arenaMode,Math.random());}));
  document.querySelectorAll('[data-boost-game]').forEach(button=>button.onclick=()=>startBoostGame(Number(button.dataset.boostGame)));
  document.querySelectorAll('[data-use-boost]').forEach(button=>button.onclick=()=>mutate(state=>state.arena.battle.selectedBoost=state.arena.battle.selectedBoost===button.dataset.useBoost?null:button.dataset.useBoost));
  document.querySelectorAll('[data-arena-skill]').forEach(button=>button.onclick=()=>mutate(state=>{const skill=state.arena.skills.find(item=>item.id===Number(button.dataset.arenaSkill));state.arena.battle=resolveArenaTurn(state.arena.battle,skill,state.arena.battle.selectedBoost,Math.random());}));
  document.querySelector('[data-claim-battle]')?.addEventListener('click',()=>mutate(state=>{const battle=state.arena.battle,win=battle.status==='victory',reward=win?45:10,delta=win?20:-9;state.arena[win?'wins':'losses']+=1;state.arena.rating=Math.max(0,state.arena.rating+delta);state.coins+=reward;state.arena.history.unshift({at:Date.now(),mode:battle.mode,result:battle.status,rival:battle.enemyName});state.arena.battle=null;state.arena.selectedMode=null;},{type:'arena',label:'Resultado de Arena registrado'}));
  document.querySelector('[data-abandon-battle]')?.addEventListener('click',()=>{modal(`<p class="eyebrow">CONFIRMAR SALIDA</p><h2>¿Abandonar esta simulación?</h2><p>El combate actual y los boosts desbloqueados se perderán.</p><button class="ghost danger full" id="confirm-abandon">ABANDONAR</button>`);document.querySelector('#confirm-abandon').onclick=()=>mutate(state=>{state.arena.battle=null;state.arena.selectedMode=null;});});
  document.querySelectorAll('[data-buy]').forEach(button => button.onclick = () => { const price = Number(button.dataset.buy); if (getState().coins < price) return toast('Monedas insuficientes'); modal(`<p class="eyebrow">CONFIRMAR COMPRA</p><h2>${button.dataset.item}</h2><button class="primary full" id="confirm-buy">CANJEAR ${price}</button>`); document.querySelector('#confirm-buy').onclick = () => { mutate(state => state.coins -= price, { type: 'reward', label: `Cosmético: ${button.dataset.item}` }); document.querySelector('#modal').innerHTML = ''; }; });
  document.querySelector('#profile')?.addEventListener('submit', event => { event.preventDefault(); mutate(state => Object.assign(state.profile, Object.fromEntries(new FormData(event.target)))); toast('Perfil actualizado'); });
  document.querySelectorAll('[data-avatar-preset]').forEach(button=>button.onclick=()=>mutate(state=>{state.profile.avatarPreset=button.dataset.avatarPreset;state.profile.avatarImage='';}));
